def distance_between_representation(model, img1_id, img2_id):
    with torch.no_grad():
        model.eval()
        z1 = model.encoder(X[img1_id].unsqueeze(0))
        z2 = model.encoder(X[img2_id].unsqueeze(0))
        return torch.dist(z1, z2).item()

